<?php
declare(strict_types=1);
require_once __DIR__ . '/../src/bootstrap.php';
$books = loadBooks();
$ids = favoriteIds();
$favorites = array_values(array_filter($books, static fn(array $book): bool => in_array((int)$book['id'], $ids, true)));
$flash = takeFlash();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Избранное — БиблиоКаталог</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="site-header"><div class="container header-inner"><a class="brand" href="index.php">📚 БиблиоКаталог</a><nav><a class="nav-link" href="index.php">Каталог</a><a class="nav-link active" href="favorites.php">Избранное <span class="count"><?= count($ids) ?></span></a></nav></div></header><main class="container page-content"><div class="section-heading"><div><p class="eyebrow">ВАША КОЛЛЕКЦИЯ</p><h1>Избранные книги</h1><p>Список сохраняется в сессии браузера.</p></div></div><?php if ($flash !== null): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php if ($favorites === []): ?><div class="empty-state"><span>♡</span><h2>Пока здесь пусто</h2><p>Добавляйте книги в избранное из каталога.</p><a class="button" href="index.php">Открыть каталог</a></div><?php else: ?><section class="book-grid"><?php foreach ($favorites as $book): ?><article class="book-card"><div class="book-cover cover-<?= (int)$book['id'] % 6 ?>"><span class="cover-icon">▤</span><span class="cover-title"><?= e($book['title']) ?></span><span class="cover-author"><?= e($book['author']) ?></span></div><div class="book-info"><div class="book-meta"><span class="genre-tag"><?= e($book['genre']) ?></span><span><?= e($book['year']) ?></span></div><h3><a href="book.php?id=<?= (int)$book['id'] ?>"><?= e($book['title']) ?></a></h3><p class="author"><?= e($book['author']) ?></p><div class="card-bottom"><a class="text-link" href="book.php?id=<?= (int)$book['id'] ?>">Подробнее →</a><form method="post" action="favorite.php"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="book_id" value="<?= (int)$book['id'] ?>"><input type="hidden" name="return_to" value="favorites.php"><button class="favorite-button is-favorite" type="submit" aria-label="Убрать из избранного">♥</button></form></div></div></article><?php endforeach; ?></section><?php endif; ?></main><footer class="site-footer"><div class="container">Учебный проект на PHP 8.4</div></footer></body></html>
